Definition inv (Mi : word -> option byte) (mdi : Model) (cri : credit) (ki : PESK.sink) (j : Z) : Prop :=
  L5.u64_at RSEGS Mi (sp - 8) (bv_unsigned (getr R (PMK.reg 1))) /\ L5.u64_at RSEGS Mi (sp - 16) (bv_unsigned (getr R (PMK.reg 8)))
  /\ L5.u64_at RSEGS Mi (sp - 24) (bv_unsigned (getr R (PMK.reg 9))) /\ L5.u64_at RSEGS Mi (sp - 32) (bv_unsigned (getr R (PMK.reg 18)))
  /\ L5C.stk (hl_sptop L) Mi sp 16384 /\ model_but_vm model mdi /\ PMSP.model_ok mdi
  /\ hi_heap HI (PESK.sink_own ki ++ LBX) cri Mi (m_vmmaps mdi)
  /\ PESK.sink_at RSEGS L PMSP.T3 PMSP.T4 P Mi o ki /\ PESK.sk_z ki = PESK.sk_z k + j /\ L5.u64_at RSEGS Mi rr o
  /\ PMK.ek L LBX sp 16384 Ws M Mi /\ PMK.dk L LBX sp 16384 M Mi
  /\ PMSP.credit_keep cr cri (PESK.sink_pot P (PESK.sk_c k)) (PESK.sink_pot P (PESK.sk_c ki)).

