(* [comment removed for export] *)
Lemma loop (m : nat) : forall (j : Z) (fxq : FPState) Rq Mq mdq crq kq,
  Z.of_nat m = 4 - 1 - j -> 0 <= j ->
  inv Mq mdq crq kq (j + 1) ->
  getr Rq (PMK.reg 2) = Z_to_bv 64 (sp - 48) -> getr Rq (PMK.reg 8) = Z_to_bv 64 rr ->
  getr Rq (PMK.reg 9) = Z_to_bv 64 (sp - 40 + j) -> getr Rq (PMK.reg 18) = Z_to_bv 64 (sp - 36) -> csl Rq ->
