Hypothesis K0 : K [].
Hypothesis ENT : PMSP.entry CAD L R M sp r 2.
Hypothesis A10 : getr R 10%bv = Z_to_bv 64 rr.
Hypothesis RRO : L5.u64_at RSEGS M rr o.
Hypothesis ALrr : rr mod 8 = 0.
Hypothesis RRlo : sp <= rr.
Hypothesis RRhi : rr + 8 <= hl_sptop L.
Hypothesis RRdj : o + 24 <= rr \/ rr + 8 <= o.
Hypothesis SKA : PESK.sink_at RSEGS L PMSP.T3 PMSP.T4 P M o k.
Hypothesis Olo : sp <= o.
Hypothesis Ohi : o + 24 <= hl_sptop L.
Hypothesis ALo : o mod 8 = 0.
Hypothesis HBh : PESK.sp_hb P h.
Hypothesis ZKB : PESK.sk_z k + 8 <= h.
Hypothesis CRED : PMSP.credit_le (PESK.sink_pot P (PESK.sk_c k)) cr.
Hypothesis KONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (cr' : credit) (k' : PESK.sink),
        regs_preserved R R' -> PESK.sk_z k' = PESK.sk_z k + 8 ->
        PESK.sink_at RSEGS L PMSP.T3 PMSP.T4 P M' o k' ->
        L5C.hpres L LBX sp (PMSP.pm_scr 2) [(o, 24)] M M' ->
        PMSP.credit_keep cr cr' (PESK.sink_pot P (PESK.sk_c k)) (PESK.sink_pot P (PESK.sk_c k')) ->
        model_but_vm model model' -> hi_heap HI (PESK.sink_own k' ++ LBX) cr' M' (m_vmmaps model') ->
        srealizes RSEGS SCFG (PMSP.cfg RSEGS R' r M' model') K.
